.fo-do-now-fab {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: auto;
  min-width: 40px;
  height: 40px;
  min-height: 40px;
  padding: 0 12px 0 10px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, #f59e0b 55%, var(--line, #1e293b));
  background: color-mix(in srgb, #f59e0b 28%, var(--panel, #111827));
  color: var(--fg, #e2e8f0);
  font: 650 13px/1 system-ui, -apple-system, sans-serif;
  cursor: pointer;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.32);
  transition: transform 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
  flex-shrink: 0;
  white-space: nowrap;
  position: relative;
}
.fo-do-now-fab[hidden] { display: none !important; }
.fo-do-now-fab.is-security {
  border-color: color-mix(in srgb, #ef4444 70%, var(--line, #1e293b));
  background: color-mix(in srgb, #ef4444 32%, var(--panel, #111827));
  animation: foDoNowPulse 1.8s ease-in-out infinite;
}
.fo-do-now-fab:hover { transform: translateY(-1px); }
.fo-do-now-fab:focus-visible { outline: 2px solid #f59e0b; outline-offset: 2px; }
.fo-do-now-fab__glyph { font-size: 16px; line-height: 1; }
.fo-do-now-fab__label { font-size: 11px; font-weight: 800; letter-spacing: 0.04em; }
.fo-do-now-fab__badge {
  position: absolute;
  top: -4px;
  right: -4px;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 999px;
  background: #dc2626;
  color: #fff;
  font: 800 10px/16px system-ui, sans-serif;
  text-align: center;
  box-shadow: 0 0 0 2px var(--panel, #111827);
}
@keyframes foDoNowPulse {
  0%, 100% { box-shadow: 0 8px 22px rgba(0, 0, 0, 0.32), 0 0 0 0 rgba(239, 68, 68, 0.45); }
  50% { box-shadow: 0 8px 22px rgba(0, 0, 0, 0.32), 0 0 0 8px rgba(239, 68, 68, 0); }
}
@media (max-width: 520px) {
  .fo-do-now-fab__label { display: none; }
  .fo-do-now-fab { padding: 0; width: 40px; }
}
html.embed-mode .fo-do-now-fab { opacity: 1; }
